# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AÇIK HAVA BASINCI VE TORİÇELLİ DENEYİ (0 °C, DENİZ SEVİYESİ)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Cıvalı Barometre Düzeneği</text>\n  <rect x="90" y="190" width="180" height="35" rx="4" fill="#94a3b8" stroke="#475569" stroke-width="1.5"/>\n  <rect x="165" y="78" width="30" height="135" rx="6" fill="#e2e8f0" stroke="#334155" stroke-width="1.5"/>\n  <rect x="167" y="105" width="26" height="108" fill="#64748b"/>\n  <text x="180" y="96" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">Boşluk</text>\n  <line x1="205" y1="105" x2="205" y2="190" stroke="#dc2626" stroke-width="2"/>\n  <text x="248" y="152" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">h = 76 cm Hg</text>\n  <text x="118" y="165" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">P0 ↓</text>\n  <text x="118" y="182" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">↓↓</text>\n  <text x="180" y="236" text-anchor="middle" font-size="11" fill="#1e3a8a">Borunun kesiti, şekli ve eğimi h yüksekliğini değiştirmez!</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Yükselti ve Sıvı Yoğunluğu Etkisi</text>\n  <polygon points="380,215 470,95 560,215" fill="#bbf7d0" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="470" y="88" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">Dağ Zirvesi: h &lt; 76 cm</text>\n  <text x="470" y="155" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">Yamaç: h ≈ 70 cm</text>\n  <text x="470" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">Deniz Seviyesi: h = 76 cm</text>\n  <text x="615" y="115" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Yükseklere</text>\n  <text x="615" y="132" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">çıkıldıkça</text>\n  <text x="615" y="149" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">P0 AZALIR!</text>\n  <text x="520" y="234" text-anchor="middle" font-size="11" fill="#14532d">Su kullanılsaydı (d_su &lt; d_cıva): h ≈ 10,3 metre olurdu</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AÇIK HAVA BASINCININ KANITLARI VE KAPALI KAP GAZ BASINCI</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Açık Hava Basıncı (P0) Örnekleri</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Magdeburg Yarım Küreleri (Otto von Guericke)</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Ters çevrilen su dolu bardaktan suyun dökülmemesi</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• İçindeki havası çekilen teneke kutunun büzülmesi</text>\n  <text x="180" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Haşlanmış yumurtanın dar şişeye kendiliğinden girmesi</text>\n  <text x="180" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Pipetle meyve suyu içilmesi ve çay tabağının yapışması</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" fill="#713f12">Cam vantuzlar ve lavabo pompasının çalışma ilkesi</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Kapalı Kaplarda Gaz Basıncı</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Taneciklerin kabın iç yüzeyine çarpmasıyla oluşur</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Kabın her noktasına EŞİT büyüklükte basınç uygulanır</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Esnek balon yükseldikçe P0 azalır ➔ Balon şişer</text>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• LPG tüpleri, yangın söndürücü, oksijen tüpü</text>\n  <text x="520" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Otomobil hava yastığı (airbag) ve tekerlekler</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" fill="#475569">Manometre ile kapalı kap gaz basıncı ölçülür</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KATI, SIVI VE GAZ BASINCININ TEKNOLOJİDEKİ UYGULAMALARI (F.8.3.1.3)</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">1. Katı Basıncı Uygulamaları</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">Basıncı Artıranlar (S küçülür):</text>\n  <text x="125" y="116" text-anchor="middle" font-size="11" fill="#881337">• Bıçak, çivi, toplu iğne ucu</text>\n  <text x="125" y="136" text-anchor="middle" font-size="11" fill="#881337">• Krampon dişleri, buz pateni</text>\n  <text x="125" y="164" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">Basıncı Azaltanlar (S büyür):</text>\n  <text x="125" y="184" text-anchor="middle" font-size="11" fill="#881337">• Kar ayakkabısı (hedik)</text>\n  <text x="125" y="204" text-anchor="middle" font-size="11" fill="#881337">• İş makinesi paleti, çok tekerlek</text>\n  <text x="125" y="224" text-anchor="middle" font-size="10" fill="#881337">• Tren rayları altındaki traversler</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">2. Sıvı Basıncı (Pascal İlkesi)</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">Sıvılar basıncı aynen iletir:</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11" fill="#164e63">• Hidrolik fren sistemleri</text>\n  <text x="350" y="138" text-anchor="middle" font-size="11" fill="#164e63">• Hidrolik lift ve krikolar</text>\n  <text x="350" y="158" text-anchor="middle" font-size="11" fill="#164e63">• İtfaiye merdiveni ve kepçeler</text>\n  <text x="350" y="178" text-anchor="middle" font-size="11" fill="#164e63">• Berber koltukları, yağdanlık</text>\n  <text x="350" y="198" text-anchor="middle" font-size="11" fill="#164e63">• Bileşik kaplar ve su cenderesi</text>\n  <text x="350" y="222" text-anchor="middle" font-size="10" fill="#0f172a">Baraj duvarları tabana doğru kalınlaşır</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">3. Gaz Basıncı Uygulamaları</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Gazlar da basıncı aynen iletir:</text>\n  <text x="575" y="118" text-anchor="middle" font-size="11" fill="#14532d">• Elektrikli süpürge ve vantuz</text>\n  <text x="575" y="138" text-anchor="middle" font-size="11" fill="#14532d">• Pipet, şırınga ve damlalık</text>\n  <text x="575" y="158" text-anchor="middle" font-size="11" fill="#14532d">• Otomobil hava yastığı (Airbag)</text>\n  <text x="575" y="178" text-anchor="middle" font-size="11" fill="#14532d">• Otobüslerin havalı kapıları</text>\n  <text x="575" y="198" text-anchor="middle" font-size="11" fill="#14532d">• Parfüm, deodorant ve spreyler</text>\n  <text x="575" y="222" text-anchor="middle" font-size="10" fill="#14532d">• Sanayi tüpleri ve kompresörler</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
